const by=s=>instruments.find(x=>x.s===s);const money=n=>'₹'+Number(n).toLocaleString('en-IN',{maximumFractionDigits:2});function nav(){document.getElementById('sidebar').innerHTML=groups.map(([g,items])=>`<div class="nav-label">${g}</div>`+items.map(name=>{let id=slugs[groups.flatMap(x=>x[1]).indexOf(name)];return `<a class="nav ${page===id?'active':''}" onclick="go('${id}')"><span class="ic">${icons[id]||'·'}</span>${name}</a>`}).join('')).join('')}
const icons={dashboard:'◫',market:'◉',scanner:'⌕',buys:'↗',sells:'↘',screener:'☷',movers:'⌁',charts:'⌗',technical:'⌬',strategies:'⎇',combinations:'⊕',assistant:'✳',setups:'⌖',backtesting:'◷',optimisation:'⤢',watchlists:'☆',paper:'▣',journal:'▤',portfolio:'▧',risk:'◈',performance:'▥',news:'▤',corporate:'▦',alerts:'♢',calendar:'▦',sources:'◌',settings:'⚙'};
function go(id){page=id;document.querySelector('.side').classList.remove('open');render()}function toast(m){let n=document.getElementById('notice');n.textContent=m;n.style.display='block';setTimeout(()=>n.style.display='none',2600)}function hdr(title,sub,act=''){return `<div class="page-head"><div><div class="eyebrow">INTRADAY AI / ${title.toUpperCase()}</div><h1>${title}</h1><div class="sub">${sub}</div></div><div class="actions">${act}</div></div>`}function demo(){return `<div class="disclaimer"><b class="amber">DEMO DATA · NOT LIVE MARKET DATA</b><br>All quotes, indicators, candidates and performance metrics on this page are illustrative sample data for interface demonstration. No market-data provider is connected. These are not trade recommendations. Connect an authorized, licensed provider before using real market information.</div>`}function badge(side){return `<span class="tag ${side.toLowerCase()}">${side}</span>`}function metrics(items){return `<div class="metrics">${items.map(([l,v,f,c])=>`<div class="card metric"><div class="label">${l}<span>ⓘ</span></div><div class="value ${c||''}">${v}</div><div class="foot">${f}</div></div>`).join('')}</div>`}function table(rows){return `<div class="table-wrap"><table><thead><tr><th>SYMBOL</th><th>LTP (DEMO)</th><th>CHANGE</th><th>REL VOL</th><th>SETUP</th><th>SCORE</th><th>STANCE</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr onclick="openSetup('${x.s}')"><td><div class="symbol">${x.s}</div><div class="subcell">${x.n}</div></td><td class="mono">${money(x.p)}</td><td class="mono ${x.c>=0?'positive':'negative'}">${x.c>0?'+':''}${x.c.toFixed(2)}%</td><td class="mono">${x.v.toFixed(1)}×</td><td>${x.strat}</td><td><span class="bar"><i style="width:${x.score}%"></i></span> <span class="mono">${x.score}</span></td><td>${badge(x.side)}</td><td><span class="watch-btn" onclick="event.stopPropagation();toggleWatch('${x.s}')">${watch.has(x.s)?'★':'☆'}</span></td></tr>`).join('')}</tbody></table></div>`}function spark(){let pts=Array.from({length:68},(_,i)=>{let y=114+Math.sin(i*.27)*24+Math.sin(i*.71)*9-i*.42+(i>40?18:0);return `${i*13},${y}`}).join(' ');let area=`0,180 ${pts} 871,180`;return `<svg viewBox="0 0 871 190" preserveAspectRatio="none"><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#38d99a" stop-opacity=".22"/><stop offset="1" stop-color="#38d99a" stop-opacity="0"/></linearGradient></defs>${[40,80,120,160].map(y=>`<line x1="0" x2="871" y1="${y}" y2="${y}" stroke="#26323d" stroke-width="1"/>`).join('')}<polygon points="${area}" fill="url(#fill)"/><polyline points="${pts}" fill="none" stroke="#38d99a" stroke-width="2"/><line x1="0" x2="871" y1="92" y2="92" stroke="#718095" stroke-dasharray="4 5"/><text x="8" y="87" fill="#8492a0" font-size="9">PREV CLOSE</text></svg>`}
function dashboard(){return `${hdr('Dashboard','Market research overview · Illustrative demo workspace',`<button class="btn" onclick="toast('Demo data refresh complete')">↻ Refresh</button><button class="btn primary" onclick="go('scanner')">Open scanner →</button>`)}${demo()}<div class="metrics">${[['NIFTY 50', '24,812.40','+0.62% today','positive'],['SENSEX','81,214.35','+0.58% today','positive'],['BANK NIFTY','51,428.70','−0.14% today','negative'],['NIFTY FIN SERVICE','23,842.15','+0.21% today','positive'],['MARKET BREADTH','1,284 / 962','advancers / decliners',''],['DEMO FEED','Unavailable','No provider connected','amber']].map(([l,v,f,c])=>`<div class="card metric"><div class="label">${l}<span class="tag demo">DEMO</span></div><div class="value ${c}">${v}</div><div class="foot">${f}</div></div>`).join('')}</div><div class="regime"><span class="reg-dot"></span><div><strong>Market regime: Uncertain / range-bound</strong><div class="section-note">Illustrative classification · mixed index breadth · strategy confidence reduced</div></div><div class="right"><div class="eyebrow">SESSION STATUS</div><div class="section-note">Demo session · not exchange linked</div></div></div><div class="grid-main"><div><section class="card section"><div class="section-head"><div class="section-title">Market pulse <span class="tag demo">DEMO</span></div><div class="tabs"><span class="tab active">NIFTY 50</span><span class="tab">BANK NIFTY</span><span class="tab">SENSEX</span></div></div><div class="chartbox">${spark()}</div><div class="chart-legend"><span><i class="dot" style="background:var(--green)"></i>Index (illustrative)</span><span>Intraday · 5 min</span><span class="mono">09:15 — 15:30 IST</span></div></section><section class="card section"><div class="section-head"><div class="section-title">Scanner candidates</div><span class="section-note">Illustrative ranking · ${instruments.length} sample symbols</span></div>${table(instruments.filter(x=>x.score>65).slice(0,6))}</section><section class="card section"><div class="section-head"><div class="section-title">₹50+ price movement finder</div><span class="tag demo">DEMO MODEL</span></div><div class="section-note">Uses illustrative ATR and available range; gross movement only, before costs. Not a forecast.</div><div class="two-col">${instruments.filter(x=>x.atr>=50).slice(0,2).map(x=>`<div class="opportunity"><b>${x.s} <span class="muted">· ${x.sector}</span></b><span class="rank">${money(x.atr)} ATR</span><div class="detail">Illustrative ATR · range space not validated</div><span>${badge('WAIT')}</span></div>`).join('')}</div></section></div><div><section class="card section"><div class="section-head"><div class="section-title">Market breadth</div><span class="section-note">Illustrative</span></div><div class="breadth"><div class="up" style="width:56%"></div><div class="down" style="width:42%"></div></div><div class="list-row"><span class="positive">Advancing</span><b>1,284</b></div><div class="list-row"><span class="negative">Declining</span><b>962</b></div><div class="list-row"><span class="muted">Unchanged</span><b>114</b></div></section><section class="card section"><div class="section-head"><div class="section-title">Sector snapshot</div><span class="section-note">DEMO</span></div>${[['Auto','+1.24%'],['Energy','+0.88%'],['Banking','+0.31%'],['IT','−0.42%'],['FMCG','−0.18%']].map(([s,v])=>`<div class="list-row"><span>${s}</span><b class="${v.startsWith('+')?'positive':'negative'}">${v}</b></div>`).join('')}</section><section class="card section"><div class="section-head"><div class="section-title">Paper trading</div><span class="section-note">Virtual account</span></div><div class="list-row"><span>Virtual capital</span><b>${money(capital)}</b></div><div class="list-row"><span>Open positions</span><b>${paperTrades.filter(t=>!t.closed).length}</b></div><div class="list-row"><span>Realized P&amp;L</span><b class="${paperTrades.filter(t=>t.closed).reduce((a,t)=>a+t.pnl,0)>=0?'positive':'negative'}">${money(paperTrades.filter(t=>t.closed).reduce((a,t)=>a+t.pnl,0))}</b></div><button class="btn small" style="margin-top:10px" onclick="go('paper')">Open paper account →</button></section><section class="card section"><div class="section-head"><div class="section-title">Data connection</div></div><div class="list-row"><span>Market feed</span><b class="amber">Not connected</b></div><div class="list-row"><span>Last update</span><b>Unavailable</b></div><div class="list-row"><span>Source</span><b>None configured</b></div><button class="btn small" style="margin-top:10px" onclick="go('sources')">Configure provider →</button></section></div></div>`}
function market(){return `${hdr('Live Market Overview','Market indices, breadth and sector performance',`<button class="btn" onclick="go('calendar')">Market calendar</button>`)}${demo()}${metrics([['NIFTY 50','24,812.40','+0.62% illustrative','positive'],['SENSEX','81,214.35','+0.58% illustrative','positive'],['BANK NIFTY','51,428.70','−0.14% illustrative','negative'],['NIFTY FIN SERVICE','23,842.15','+0.21% illustrative','positive'],['ADVANCERS','1,284','sample breadth','positive'],['DECLINERS','962','sample breadth','negative']])}<div class="two-col"><section class="card section"><div class="section-head"><div class="section-title">Index performance</div><span class="section-note">Illustrative sample</span></div>${[['NIFTY 50','+0.62%'],['SENSEX','+0.58%'],['BANK NIFTY','−0.14%'],['NIFTY IT','−0.42%'],['NIFTY AUTO','+1.24%'],['NIFTY MIDCAP 100','+0.84%']].map(([s,v])=>`<div class="list-row"><span>${s}</span><b class="${v.startsWith('+')?'positive':'negative'}">${v}</b></div>`).join('')}</section><section class="card section"><div class="section-head"><div class="section-title">Breadth &amp; regime</div></div><div class="regime"><span class="reg-dot"></span><div><strong>Uncertain / range-bound</strong><div class="section-note">Illustrative model; feed is not connected</div></div></div><div class="breadth"><div class="up" style="width:56%"></div><div class="down" style="width:42%"></div></div><div class="list-row"><span>Advancing / declining</span><b>1,284 / 962</b></div><div class="list-row"><span>New 52-week highs / lows</span><b>42 / 19</b></div></section></div>`}
function scanner(){let rows=instruments.filter(x=>activeFilter==='ALL'||x.side===activeFilter);return `${hdr('AI Intraday Scanner','Strategy consensus with transparent signal context',`<button class="btn" onclick="toast('No provider connected · sample data unchanged')">↻ Refresh</button><button class="btn primary" onclick="go('setups')">Trade setups →</button>`)}${demo()}<div class="filterbar"><span class="field-label">VIEW</span>${['ALL','BUY','SELL','WAIT'].map(f=>`<button class="btn small ${activeFilter===f?'primary':''}" onclick="activeFilter='${f}';render()">${f}</button>`).join('')}<select class="field" onchange="scannerSort(this.value)"><option value="score">Sort: Score</option><option value="move">ATR movement</option><option value="volume">Relative volume</option></select><input class="field" id="scanSearch" placeholder="Filter symbol…" oninput="scannerSearch(this.value)"><span class="section-note">${rows.length} illustrative samples · full universe not loaded</span></div><section class="card section"><div class="section-head"><div class="section-title">Candidates</div><span class="section-note">Score ≠ probability of profit</span></div><div id="scanTable">${table(rows)}</div></section><div class="two-col"><section class="card section"><div class="section-title">Consensus rules</div><div class="list-row"><span>Independent strategy families</span><b>Not simple indicator count</b></div><div class="list-row"><span>Conflicts</span><b>Downgrade to WAIT</b></div><div class="list-row"><span>Feed freshness</span><b class="amber">Unavailable</b></div></section><section class="card section"><div class="section-title">Price movement filter</div><div class="form-grid" style="margin-top:12px"><div class="form-item"><label>Minimum gross movement</label><select id="minMove" class="field"><option>20</option><option>30</option><option selected>50</option><option>75</option><option>100</option></select></div><div class="form-item"><label>Horizon</label><select class="field"><option>Intraday</option><option>1 day</option><option>5 days</option></select></div><div class="form-item"><label>Method</label><select class="field"><option>ATR + structure</option><option>Dynamic best</option></select></div></div><button class="btn small" style="margin-top:10px" onclick="toast('No sample qualifies as a validated ₹50+ setup; live feed unavailable')">Find opportunities</button></section></div>`}
function scannerSort(k){if(k==='move')instruments.sort((a,b)=>b.atr-a.atr);if(k==='volume')instruments.sort((a,b)=>b.v-a.v);if(k==='score')instruments.sort((a,b)=>b.score-a.score);render()}function scannerSearch(v){let rows=instruments.filter(x=>(activeFilter==='ALL'||x.side===activeFilter)&&`${x.s} ${x.n}`.toLowerCase().includes(v.toLowerCase()));document.getElementById('scanTable').innerHTML=table(rows)}
function screener(){return `${hdr('Stock Screener','Filter the available sample universe using transparent criteria')}${demo()}<div class="card section"><div class="filterbar"><input class="field" id="filterSearch" placeholder="Symbol or company" oninput="renderScreener()"><select class="field" id="filterSide" onchange="renderScreener()"><option>ALL</option><option>BUY</option><option>SELL</option><option>WAIT</option></select><select class="field" id="filterSector" onchange="renderScreener()"><option>All sectors</option>${[...new Set(instruments.map(x=>x.sector))].map(s=>`<option>${s}</option>`).join('')}</select><label class="field-label">Rel vol ≥ <input class="field" id="filterVol" type="number" value="0" step="0.2" style="width:70px" oninput="renderScreener()"></label><label class="field-label">Score ≥ <input class="field" id="filterScore" type="number" value="0" style="width:65px" oninput="renderScreener()"></label><button class="btn small" onclick="document.getElementById('filterSearch').value='';document.getElementById('filterSide').value='ALL';document.getElementById('filterSector').value='All sectors';document.getElementById('filterVol').value=0;document.getElementById('filterScore').value=0;renderScreener()">Reset</button><button class="btn small" onclick="toast('Screener saved to this browser session')">Save screener</button></div><div id="screenerTable">${table(instruments)}</div></div>`}
function renderScreener(){let q=document.getElementById('filterSearch')?.value.toLowerCase()||'',side=document.getElementById('filterSide')?.value||'ALL',sect=document.getElementById('filterSector')?.value||'All sectors',vol=+(document.getElementById('filterVol')?.value||0),score=+(document.getElementById('filterScore')?.value||0);let r=instruments.filter(x=>(x.s+' '+x.n).toLowerCase().includes(q)&&(side==='ALL'||x.side===side)&&(sect==='All sectors'||x.sector===sect)&&x.v>=vol&&x.score>=score);document.getElementById('screenerTable').innerHTML=table(r)}
function buysells(which){let data=instruments.filter(x=>x.side===which);return `${hdr(which==='BUY'?'Best BUY Opportunities':'Best SELL Opportunities','Ranked illustrative candidates · stance is not a recommendation')}${demo()}<section class="card section"><div class="section-head"><div class="section-title">${which} candidates</div><span class="section-note">${data.length} samples · no live validation · score is not probability</span></div>${data.length?table(data):'<div class="empty"><b>NO HIGH-QUALITY TRADE OPPORTUNITY CURRENTLY AVAILABLE.</b>No sample candidates match. A live feed is required to qualify genuine setups.</div>'}</section>`}
function movers(){return `${hdr('Market Movers','Illustrative gainers, decliners and unusual volume')}${demo()}<div class="two-col">${[['Top gainers',instruments.filter(x=>x.c>0).sort((a,b)=>b.c-a.c)],['Top decliners',instruments.filter(x=>x.c<0).sort((a,b)=>a.c-b.c)],['Relative volume',instruments.slice().sort((a,b)=>b.v-a.v)],['High ATR (₹)',instruments.slice().sort((a,b)=>b.atr-a.atr)]].map(([title,arr])=>`<section class="card section"><div class="section-head"><div class="section-title">${title}</div><span class="tag demo">DEMO</span></div>${arr.slice(0,5).map(x=>`<div class="list-row" onclick="openSetup('${x.s}')"><span>${x.s}<small class="muted"> · ${x.n}</small></span><b class="${title==='Top decliners'?'negative':'positive'}">${title==='Relative volume'?x.v+'×':title==='High ATR (₹)'?money(x.atr):`${x.c>0?'+':''}${x.c}%`}</b></div>`).join('')}</section>`).join('')}</div>`}
function openSetup(s){let x=by(s);if(!x)return;page='setups';render();let select=document.getElementById('setupSymbol');if(select)select.value=s;renderSetup(x)}
function charts(){return `${hdr('Advanced Charts','Candlestick workspace · sample series only',`<button class="btn" onclick="toast('Drawing tools are unavailable in this preview')">＋ Drawing</button>`)}${demo()}<section class="card section"><div class="filterbar"><select class="field" id="chartSymbol" onchange="renderChartSymbol()">${instruments.map(x=>`<option>${x.s}</option>`).join('')}</select>${['1m','3m','5m','15m','1h','1D'].map((x,i)=>`<button class="btn small ${i===2?'primary':''}" onclick="this.parentNode.querySelectorAll('button').forEach(b=>b.classList.remove('primary'));this.classList.add('primary');toast('Illustrative ${x} series selected')">${x}</button>`).join('')}<select class="field"><option>EMA 20 + VWAP</option><option>Bollinger Bands</option><option>Supertrend</option><option>Volume</option></select></div><div class="chartbox" style="height:330px">${spark()}</div><div class="chart-legend"><span><i class="dot" style="background:var(--green)"></i>Illustrative price</span><span>Sample series · not exchange candles</span></div></section><div class="two-col"><section class="card section"><div class="section-title">Chart explanation</div><p class="muted">No price candles loaded from an authorized market-data source. The chart line is a generated illustration and cannot be used to inspect actual candles or signal triggers.</p></section><section class="card section"><div class="section-title">Chart overlays</div>${['VWAP','EMA 9 / 20','Support / resistance','Volume','RSI panel'].map(a=>`<div class="list-row"><span>${a}</span><input type="checkbox" onchange="toast('${a} overlay control · sample chart only')"></div>`).join('')}</section></div>`}
function technical(){return `${hdr('Technical Analysis','Indicator library and interpretation reference')}${demo()}<div class="filterbar"><select class="field">${instruments.map(x=>`<option>${x.s}</option>`).join('')}</select><select class="field"><option>5 minute</option><option>15 minute</option><option>Daily</option></select><input class="field" placeholder="Search indicator" oninput="document.querySelectorAll('.ind-row').forEach(r=>r.style.display=r.dataset.n.includes(this.value.toLowerCase())?'':'none')"></div><section class="card section"><div class="section-head"><div class="section-title">Indicator catalogue</div><span class="section-note">Sample values are unavailable until real candles are connected</span></div><table><thead><tr><th>INDICATOR</th><th>FAMILY</th><th>PARAMETERS</th><th>VALUE</th><th>INTERPRETATION</th></tr></thead><tbody>${[['EMA','Trend','5, 9, 20, 50, 200'],['SMA','Trend','5, 10, 20, 50, 100, 200'],['VWAP','Trend / volume','Session'],['Supertrend','Trend','10, 3'],['Ichimoku Cloud','Trend','9, 26, 52'],['Parabolic SAR','Trend','0.02, 0.2'],['RSI','Momentum','14'],['Stochastic RSI','Momentum','14, 14, 3, 3'],['MACD','Momentum','12, 26, 9'],['ADX / DMI','Momentum','14'],['ATR','Volatility','14'],['Bollinger Bands','Volatility','20, 2'],['Keltner Channels','Volatility','20, 1.5'],['OBV','Volume','—'],['MFI','Volume','14'],['CMF','Volume','20'],['Relative Volume','Volume','20'],['Pivot / CPR','Support / resistance','Classic'],['Fibonacci levels','Support / resistance','Swing based'],['Anchored VWAP','Trend','User anchor'],['DEMA / TEMA / KAMA / HMA','Trend','Configurable'],['CCI / ROC / Williams %R / TRIX / Aroon','Momentum','Configurable'],['Donchian / HV / Chaikin Volatility','Volatility','Configurable'],['Force Index / Ease of Movement','Volume','Configurable']].map(([n,f,p])=>`<tr class="ind-row" data-n="${(n+' '+f).toLowerCase()}"><td class="symbol">${n}</td><td>${f}</td><td class="mono">${p}</td><td class="muted">Unavailable</td><td class="muted">Requires licensed candles</td></tr>`).join('')}</tbody></table></section>`}
const strategies=['Opening Range Breakout','Initial Balance Breakout','Previous Day High/Low','NR4 / NR7','Inside Bar Breakout','Volume Confirmed Breakout','VWAP Reclaim / Rejection','EMA 9/20 Crossover','EMA Pullback','RSI Momentum / Divergence','MACD Crossover','ADX Trend Strength','Supertrend','Parabolic SAR','Multi-Timeframe Trend','Bollinger Band Reversal','Support / Resistance Rejection','Candlestick Patterns','Relative Volume Surge','Bollinger Squeeze','Gap and Go / Gap Fill','Market Breadth Confirmation','Mean Reversion / Z-Score','Momentum Ranking','Pairs Trading Research','Regime-Based Selection'];
function strategyPage(combo=false){return `${hdr(combo?'Strategy Combinations':'Strategy Library',combo?'Combine independent strategy families for research':'Extensible strategy catalogue · enable strategies to configure a research set',`<button class="btn" onclick="toast('Strategy selection saved in this browser')">Save selection</button>`)}${demo()}<div class="two-col"><section class="card section"><div class="section-head"><div class="section-title">${combo?'Select strategy components':'Available strategy families'}</div><span class="section-note">${strategies.length} catalogue entries</span></div><div style="max-height:530px;overflow:auto">${strategies.map((s,i)=>`<label class="strategy"><input type="checkbox" ${i<4?'checked':''}><span>${s}</span><span>${i<6?'Breakout':'Research only'}</span></label>`).join('')}</div><button class="btn primary" style="margin-top:12px" onclick="toast('Selections saved · no live candles available for execution')">${combo?'Save combination':'Enable selected'}</button></section><section><section class="card section"><div class="section-title">Strategy framework status</div><p class="muted">Catalogue and configuration controls are available. Live strategy execution requires market candles and tested, strategy-specific rules. No strategy backtest results are preloaded.</p><div class="list-row"><span>Definitions in catalogue</span><b>${strategies.length}</b></div><div class="list-row"><span>Strategies live-tested</span><b class="amber">0</b></div><div class="list-row"><span>Current regime adaptation</span><b>Unavailable</b></div></section><section class="card section"><div class="section-title">Consensus guardrails</div>${['Correlated indicators do not count as independent evidence','Conflicting strategies downgrade candidate to WAIT','Liquidity, feed freshness and entry validity are mandatory','Historical performance requires out-of-sample validation'].map(x=>`<div class="list-row"><span>✓ ${x}</span></div>`).join('')}</section></section></div>`}
function assistant(){return `${hdr('AI Trading Assistant','Grounded answers from connected application data only')}${demo()}<section class="card section"><div class="section-title">Ask about market data</div><p class="muted">The assistant cannot make verified market claims while the feed is disconnected. Try a demo query to see the response boundary.</p><div class="filterbar"><input class="field" id="ask" style="flex:1;min-width:200px" placeholder="e.g. Which sample stocks are above VWAP?"><button class="btn primary" onclick="askAI()">Ask</button></div><div class="filterbar">${['Strongest momentum?','₹50+ movement candidates?','Why is this WAIT?','What invalidates the setup?'].map(q=>`<button class="btn small" onclick="document.getElementById('ask').value='${q}';askAI()">${q}</button>`).join('')}</div><div id="answer"></div></section><section class="card section"><div class="section-title">Data policy</div><div class="list-row"><span>Verified live data</span><b class="amber">Unavailable</b></div><div class="list-row"><span>Historical feed</span><b>Not connected</b></div><div class="list-row"><span>Model analysis</span><b>Sample heuristics only</b></div><div class="list-row"><span>Source references</span><b>None</b></div></section>`}function askAI(){let q=document.getElementById('ask').value;document.getElementById('answer').innerHTML=`<div class="result-box"><b>Data unavailable for a verified answer.</b><br>Your question: “${q.replace(/[<>]/g,'')}”<br>The market-data provider is not connected. Sample rows are illustrative and cannot support a real market conclusion. Connect a licensed feed to enable data-grounded answers.</div>`}
function risk(){return `${hdr('Risk Management','Position sizing with fees, slippage and capital limits')}${demo()}<div class="two-col"><section class="card section"><div class="section-title">Position size calculator</div><div class="form-grid" style="margin-top:13px"><div class="form-item"><label>Available capital (₹)</label><input id="rCapital" type="number" value="${capital}" oninput="calcRisk()"></div><div class="form-item"><label>Risk per trade (%)</label><input id="rPct" type="number" value="0.5" step="0.1" oninput="calcRisk()"></div><div class="form-item"><label>Entry price (₹)</label><input id="rEntry" type="number" value="1000" oninput="calcRisk()"></div><div class="form-item"><label>Stop loss (₹)</label><input id="rStop" type="number" value="980" oninput="calcRisk()"></div><div class="form-item"><label>Estimated costs per share (₹)</label><input id="rCost" type="number" value="1.5" step="0.1" oninput="calcRisk()"></div><div class="form-item"><label>Maximum positions</label><input id="rMax" type="number" value="3" min="1" oninput="calcRisk()"></div></div><div class="result-box" id="riskResult"></div></section><section class="card section"><div class="section-title">Capital protection</div>${['Daily loss circuit breaker','Maximum sector exposure','Maximum trades per day','Margin and lot size','Exchange restrictions','Liquidity and slippage'].map((s,i)=>`<div class="list-row"><span>${s}</span><b>${i===0?'Configurable':'Needs account / broker data'}</b></div>`).join('')}<div class="form-item" style="margin-top:12px"><label>Daily loss limit (₹)</label><input id="dailyLimit" type="number" value="5000"></div><button class="btn small" style="margin-top:9px" onclick="toast('Daily limit saved for this session')">Set limit</button></section></div><script>calcRisk()<\/script>`}
function calcRisk(){let cap=+document.getElementById('rCapital')?.value,pct=+document.getElementById('rPct')?.value,entry=+document.getElementById('rEntry')?.value,stop=+document.getElementById('rStop')?.value,cost=+document.getElementById('rCost')?.value,max=+document.getElementById('rMax')?.value||1;let dist=Math.abs(entry-stop),risk=cap*pct/100,qRaw=dist?Math.floor(risk/(dist+cost)):0,qAfford=entry?Math.floor(cap/(entry+cost)):0,qty=Math.min(qRaw,qAfford),loss=qty*(dist+cost);let el=document.getElementById('riskResult');if(el)el.innerHTML=`Risk budget: <b>${money(risk)}</b><br>Risk/share incl. estimated cost: <b>${money(dist+cost)}</b><br>Position quantity: <b>${qty.toLocaleString('en-IN')} shares</b> <span class="muted">(capital-capped)</span><br>Maximum estimated loss: <b class="negative">${money(loss)}</b><br>Capital at entry: <b>${money(qty*entry)}</b><br>Max open positions setting: ${max}<br><span class="muted">Excludes broker margin, statutory fees and actual slippage. No broker data connected.</span>`}
function paper(){let open=paperTrades.filter(t=>!t.closed),closed=paperTrades.filter(t=>t.closed);open.forEach(t=>{let mark=by(t.s)?.p||t.entry;t.unreal=(t.side==='BUY'?mark-t.entry:t.entry-mark)*t.qty});let pnl=closed.reduce((a,t)=>a+t.pnl,0),unreal=open.reduce((a,t)=>a+t.unreal,0);return `${hdr('Paper Trading','Virtual orders with illustrative fills · no broker connection',`<button class="btn" onclick="go('risk')">Risk calculator</button><button class="btn primary" onclick="openOrder()">＋ New paper order</button>`)}${demo()}${metrics([['VIRTUAL CAPITAL',money(capital),'Saved in this browser',''],['OPEN POSITIONS',open.length,'Paper only',''],['REALIZED P&L',money(pnl),'After illustrative costs',pnl>=0?'positive':'negative'],['UNREALIZED P&L',money(unreal),'Illustrative marks only',unreal>=0?'positive':'negative'],['CLOSED TRADES',closed.length,'All outcomes retained',''],['EXECUTION','Simulated','Slippage not calibrated','amber']])}<section class="card section"><div class="tabs"><span class="tab active">Open positions (${open.length})</span><span class="tab" onclick="showClosed()">Closed trades (${closed.length})</span></div><div id="paperRows">${open.length?paperTable(open):'<div class="empty"><b>No open paper positions</b>Start a virtual trade to track entry, stop and target behaviour.</div>'}</div></section><section class="card section"><div class="section-title">Paper order</div><div class="form-grid" style="margin-top:12px"><div class="form-item"><label>Virtual capital (₹)</label><input id="pcap" type="number" value="${capital}"></div><div class="form-item"><label>Simulated slippage (bps)</label><input id="slippage" type="number" value="5"></div><div class="form-item"><label>Estimated charges / side (₹)</label><input id="charges" type="number" value="20"></div></div><button class="btn small" style="margin-top:10px" onclick="savePaperSettings()">Save paper settings</button></section>`}function paperTable(rows){return `<div class="table-wrap"><table><thead><tr><th>SYMBOL</th><th>SIDE</th><th>QTY</th><th>ENTRY</th><th>STOP</th><th>MARK (DEMO)</th><th>UNREAL P&amp;L</th><th></th></tr></thead><tbody>${rows.map(t=>`<tr><td>${t.s}</td><td>${badge(t.side)}</td><td>${t.qty}</td><td class="mono">${money(t.entry)}</td><td class="mono">${money(t.stop)}</td><td class="mono">${money(by(t.s)?.p||t.entry)}</td><td class="mono ${t.unreal>=0?'positive':'negative'}">${money(t.unreal)}</td><td><button class="btn small" onclick="closeTrade('${t.id}')">Close</button></td></tr>`).join('')}</tbody></table></div>`}function openOrder(){let sym=prompt('Sample symbol (illustrative demo only): '+instruments.map(x=>x.s).join(', '));if(!sym)return;let x=by(sym.toUpperCase());if(!x)return toast('Choose a symbol from the sample universe');let side=(prompt('Side: BUY or SELL','BUY')||'').toUpperCase();if(!['BUY','SELL'].includes(side))return toast('Side must be BUY or SELL');let stop=side==='BUY'?x.p-x.atr:x.p+x.atr,qty=Math.max(1,Math.floor((capital*.005)/x.atr));let t={id:Date.now().toString(),s:x.s,side,qty,entry:x.p,stop,unreal:0,closed:false,time:new Date().toISOString()};paperTrades.push(t);journalLog.push({...t,type:'signal'});saveStore();render();toast('Illustrative paper '+side+' recorded for '+qty+' '+x.s+' at '+money(x.p))}function closeTrade(id){let t=paperTrades.find(x=>x.id===id);if(!t)return;let mark=by(t.s)?.p||t.entry;t.pnl=(mark-t.entry)*t.qty-40;t.closed=true;t.close=mark;t.unreal=0;saveStore();render();toast('Paper position closed at illustrative sample mark')}function showClosed(){let e=document.getElementById('paperRows'),r=paperTrades.filter(t=>t.closed);e.innerHTML=r.length?`<table><thead><tr><th>SYMBOL</th><th>QTY</th><th>ENTRY</th><th>EXIT</th><th>NET P&amp;L (DEMO)</th><th>CLOSED</th></tr></thead><tbody>${r.map(t=>`<tr><td>${t.s}</td><td>${t.qty}</td><td>${money(t.entry)}</td><td>${money(t.close)}</td><td class="${t.pnl>=0?'positive':'negative'}">${money(t.pnl)}</td><td>${new Date().toLocaleDateString()}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No closed trades</div>'}function savePaperSettings(){capital=+document.getElementById('pcap').value;localStorage.setItem('ia_capital',capital);toast('Virtual capital saved')}function saveStore(){localStorage.setItem('ia_paper',JSON.stringify(paperTrades));localStorage.setItem('ia_journal',JSON.stringify(journalLog))}
function watchlists(){return `${hdr('Watchlists','Local browser watchlist · no account sync',`<button class="btn primary" onclick="addWatch()">＋ Add symbol</button>`)}${demo()}<section class="card section"><div class="section-head"><div class="section-title">My watchlist</div><span class="section-note">${watch.size} symbols · saved in this browser</span></div>${watch.size?table([...watch].map(by).filter(Boolean)):'<div class="empty"><b>Your watchlist is empty</b>Add a symbol to follow its illustrative data.</div>'}</section>`}function toggleWatch(s){watch.has(s)?watch.delete(s):watch.add(s);toast(watch.has(s)?`${s} added to watchlist`:`${s} removed`);if(page==='watchlists')render();else render()}function addWatch(){let s=prompt('Enter a symbol from the sample universe: '+instruments.map(x=>x.s).join(', '));if(!s)return;let x=by(s.toUpperCase());if(!x)return toast('Symbol is not in the available sample universe');watch.add(x.s);render();toast(`${x.s} added`)}
function backtest(){return `${hdr('Backtesting','Historical strategy research · no historical feed configured')}${demo()}<section class="card section"><div class="section-title">Configure backtest</div><div class="form-grid" style="margin-top:13px"><div class="form-item"><label>Symbol</label><select id="btSymbol">${instruments.map(x=>`<option>${x.s}</option>`).join('')}</select></div><div class="form-item"><label>Strategy</label><select id="btStrategy">${strategies.map(s=>`<option>${s}</option>`).join('')}</select></div><div class="form-item"><label>Timeframe</label><select id="btFrame"><option>5 minute</option><option>15 minute</option><option>Daily</option></select></div><div class="form-item"><label>From</label><input id="btFrom" type="date"></div><div class="form-item"><label>To</label><input id="btTo" type="date"></div><div class="form-item"><label>Capital (₹)</label><input id="btCap" type="number" value="${capital}"></div><div class="form-item"><label>Brokerage + fees / trade (₹)</label><input id="btFees" type="number" value="40"></div><div class="form-item"><label>Slippage (bps)</label><input id="btSlip" type="number" value="5"></div><div class="form-item"><label>Stop method</label><select><option>ATR × 1.5</option><option>Swing structure</option><option>Fixed risk/reward</option></select></div></div><div class="filterbar" style="margin-top:14px"><button class="btn primary" onclick="runBacktest()">Run backtest</button><label><input type="checkbox" checked> Out-of-sample split</label><label><input type="checkbox"> Walk-forward (requires historical data)</label></div><div id="btOutput">${btResult||''}</div></section><section class="card section"><div class="section-title">Backtest integrity</div><div class="list-row"><span>Look-ahead bias prevention</span><b>Required</b></div><div class="list-row"><span>Survivorship-bias control</span><b>Instrument history required</b></div><div class="list-row"><span>Out-of-sample validation</span><b>Not run</b></div><div class="list-row"><span>Historical candles loaded</span><b class="amber">0</b></div></section>`}function runBacktest(){btResult=`<div class="result-box"><b class="amber">Backtest not run</b><br>No historical candle data is configured. Metrics such as win rate, profit factor, drawdown and Sharpe ratio are withheld rather than fabricated. Connect an authorized historical data source to run this strategy.</div>`;document.getElementById('btOutput').innerHTML=btResult}
function setups(){return `${hdr('Trade Setup Details','Inspect entry logic, risk and invalidation conditions')}${demo()}<div class="filterbar"><select class="field" id="setupSymbol" onchange="renderSetup(by(this.value))">${instruments.map(x=>`<option>${x.s}</option>`).join('')}</select></div><div id="setupDetail"></div>`}
function renderSetup(x){if(!x)x=instruments[0];if(page!=='setups'){page='setups';render()}let e=document.getElementById('setupDetail');if(!e)return;let stop=x.p-x.atr,entry=x.p,dist=Math.abs(entry-stop),risk=capital*.005,qty=Math.floor(risk/dist);e.innerHTML=`<div class="two-col"><section class="card section"><div class="section-head"><div><div class="section-title">${x.s} · ${x.n}</div><div class="section-note">NSE sample · ${x.sector}</div></div>${badge(x.side)}</div><div class="list-row"><span>Illustrative LTP</span><b>${money(x.p)}</b></div><div class="list-row"><span>Sample strategy label</span><b>${x.strat}</b></div><div class="list-row"><span>Entry trigger</span><b class="amber">Not validated</b></div><div class="list-row"><span>Entry reference</span><b>${money(entry)} (demo only)</b></div><div class="list-row"><span>Stop reference (ATR)</span><b>${money(stop)}</b></div><div class="list-row"><span>Target 1 / 2 / 3 (1.5R / 2R / 3R)</span><b>${money(entry+dist*1.5)} / ${money(entry+dist*2)} / ${money(entry+dist*3)}</b></div><div class="list-row"><span>Reward / risk</span><b>1.5R / 2R / 3R</b></div><div class="list-row"><span>Gross ₹50+ potential</span><b class="amber">Unvalidated · ATR ${money(x.atr)}</b></div><div class="list-row"><span>Suggested quantity reference</span><b>${qty} shares at 0.5% risk</b></div><div class="list-row"><span>Signal timestamp / expiry</span><b>Unavailable · feed disconnected</b></div></section><section><section class="card section"><div class="section-title">Why this sample is ${x.side}</div><p class="muted">${x.strat} is a sample label. The scanner candidate is illustrative and has not been produced from actual candles. No real trade entry is valid from this page.</p><div class="list-row"><span>Supporting strategies</span><b>Unverified</b></div><div class="list-row"><span>Conflicting strategies</span><b>Unverified</b></div><div class="list-row"><span>Liquidity / spread</span><b>Unavailable</b></div><div class="list-row"><span>Invalidation</span><b>Feed staleness / structure break</b></div></section><button class="btn" onclick="go('paper')">Record paper trade →</button><div class="disclaimer" style="margin-top:12px">Paper trades opened through the paper account use a demo mark and are not executable recommendations.</div></section></div>`}
function paperPage(){return paper()}
function journalPage(){return `${hdr('Trade Journal','Signal log and paper-trade history · losing outcomes retained',`<button class="btn" onclick="exportJournal()">↓ Export CSV</button>`)}${demo()}<section class="card section"><div class="section-head"><div class="section-title">Recorded signals and trades</div><input class="field" id="journalSearch" placeholder="Filter symbol" oninput="renderJournal()"></div><div id="journalTable"></div></section>`}function renderJournal(){let el=document.getElementById('journalTable');if(!el)return;let q=document.getElementById('journalSearch')?.value.toLowerCase()||'',r=[...paperTrades].filter(x=>x.s.toLowerCase().includes(q));el.innerHTML=r.length?`<table><thead><tr><th>TIME</th><th>SYMBOL</th><th>SIDE</th><th>ENTRY</th><th>STOP</th><th>STATUS</th><th>NET P&amp;L (DEMO)</th></tr></thead><tbody>${r.map(x=>`<tr><td>${new Date(x.time).toLocaleString()}</td><td>${x.s}</td><td>${x.side}</td><td>${money(x.entry)}</td><td>${money(x.stop)}</td><td>${x.closed?'Closed':'Open'}</td><td class="${(x.pnl||0)>=0?'positive':'negative'}">${x.closed?money(x.pnl):'—'}</td></tr>`).join('')}</tbody></table>`:'<div class="empty"><b>No recorded paper trades</b>Signals are logged when you open an illustrative paper order.</div>'}function exportJournal(){let rows=[['time','symbol','side','quantity','entry','stop','close','net_pnl','status'],...paperTrades.map(t=>[t.time,t.s,t.side,t.qty,t.entry,t.stop,t.close||'',t.pnl||'',t.closed?'closed':'open'])];let csv=rows.map(r=>r.join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='intraday-ai-paper-journal.csv';a.click()}
function performance(){let closed=paperTrades.filter(t=>t.closed),wins=closed.filter(t=>t.pnl>0).length,pnl=closed.reduce((a,t)=>a+t.pnl,0);return `${hdr('Performance Analytics','Metrics from saved paper trades only')}${demo()}${metrics([['CLOSED TRADES',closed.length,'Paper account',''],['WIN RATE',closed.length?(wins/closed.length*100).toFixed(1)+'%':'—','No trades is not 0%',''],['NET P&L',money(pnl),'Demo fill estimates',pnl>=0?'positive':'negative'],['PROFIT FACTOR','—','Requires trade sample',''],['MAX DRAWDOWN','—','Requires equity curve',''],['EXPECTANCY','—','Not estimated','']])}<section class="card section"><div class="section-title">Strategy comparison</div><div class="empty"><b>No validated strategy performance</b>Historical candles and out-of-sample backtests are not connected. Paper trades alone are not enough to claim strategy edge.</div></section><button class="btn" onclick="go('backtesting')">Configure backtest →</button>`}
function portfolio(){return `${hdr('Portfolio Tracker','Holdings and returns · separate from paper trading')}${demo()}<div class="empty"><b>No portfolio holdings added</b>Portfolio data is separate from the virtual paper account. Add holdings after configuring a persistent account backend.</div><section class="card section" style="margin-top:13px"><div class="section-title">Portfolio capabilities</div>${['Average purchase price','Current value and unrealized P&L','Realized P&L','Corporate action adjustments'].map(x=>`<div class="list-row"><span>${x}</span><b>Requires account-backed persistence and verified prices</b></div>`).join('')}</section>`}
function alerts(){return `${hdr('Alerts and Notifications','Configure local research alerts')}${demo()}<div class="two-col"><section class="card section"><div class="section-title">Create alert</div><div class="form-grid" style="margin-top:12px"><div class="form-item"><label>Symbol</label><select class="field">${instruments.map(x=>`<option>${x.s}</option>`).join('')}</select></div><div class="form-item"><label>Alert type</label><select class="field"><option>Price crosses</option><option>Relative volume surge</option><option>VWAP crossover</option><option>RSI threshold</option><option>Breakout / breakdown</option><option>Signal invalidation</option><option>Daily loss limit</option></select></div><div class="form-item"><label>Condition value</label><input type="number" placeholder="Enter a threshold"></div></div><button class="btn primary small" style="margin-top:11px" onclick="toast('Alert configuration saved locally; requires live feed to trigger')">Save alert</button></section><section class="card section"><div class="section-title">Delivery channels</div>${['In-app','Browser notifications','Email','Mobile push','Telegram'].map((x,i)=>`<div class="list-row"><span>${x}</span><b>${i===0?'Available locally':'Not configured'}</b></div>`).join('')}</section></div><section class="card section"><div class="section-title">Alert deduplication</div><p class="muted">Frequency controls and duplicate suppression need a persistent event service. No alerts can trigger until a provider feed is connected.</p><div class="list-row"><span>Feed disconnection alert</span><b class="amber">Provider already disconnected</b></div></section>`}
function sources(){return `${hdr('Data Source Monitor','Licensed provider integration and feed health')}${demo()}<div class="regime"><span class="reg-dot"></span><div><strong>No market data provider configured</strong><div class="section-note">Quotes, candles, instruments and exchange timestamps unavailable</div></div><div class="right"><span class="tag wait">DISCONNECTED</span></div></div><div class="two-col"><section class="card section"><div class="section-title">Provider connection</div><div class="form-grid" style="margin-top:12px"><div class="form-item"><label>Provider adapter</label><select class="field"><option>TrueData (licensed account required)</option><option>Authorized broker API</option><option>Other licensed provider</option></select></div><div class="form-item"><label>Environment</label><select class="field"><option>Demo</option><option>Production</option></select></div><div class="form-item"><label>Credential reference (server-side)</label><input placeholder="Configure in backend environment" disabled></div></div><button class="btn primary small" style="margin-top:10px" onclick="toast('Provider adapter interface is ready; backend credentials and subscription required')">Check integration requirements</button><p class="muted">Never enter provider secrets in this browser. Credentials must be stored server-side.</p></section><section class="card section"><div class="section-title">Feed health</div>${[['LTP / bid / ask','Unavailable'],['Candles / intervals','Unavailable'],['Instrument master','Not loaded'],['Exchange timestamp','Unavailable'],['Staleness monitor','No feed'],['WebSocket reconnect','Backend adapter required'],['Licensing status','Not verified']].map(([a,b])=>`<div class="list-row"><span>${a}</span><b class="amber">${b}</b></div>`).join('')}</section></div><section class="card section"><div class="section-title">Integration notes</div><p class="muted">Select an NSE/BSE-authorized or otherwise licensed provider. Confirm your subscription covers real-time data, historical intraday candles, websocket redistribution, exchange identifiers and intended usage. This demo workspace does not connect to Yahoo Finance or scrape exchange pages.</p></section>`}
function news(){return `${hdr('Market News','News and disclosures require licensed or authorized sources')}${demo()}<div class="tabs"><span class="tab active">Market</span><span class="tab">Company</span><span class="tab">Corporate events</span></div><div class="empty"><b>No news source connected</b>Headlines, publication timestamps and event notices are unavailable. No sample headlines are shown as real news.</div>`}function corporate(){return `${hdr('Corporate Announcements','Exchange announcements and company events')}${demo()}<div class="filterbar"><input class="field" type="date"><select class="field"><option>All event types</option><option>Results</option><option>Dividend</option><option>Split / bonus</option><option>Bulk / block deals</option></select><input class="field" placeholder="Filter symbol"></div><div class="empty"><b>No announcements feed configured</b>Company events require an authorized source with publication timestamps and source attribution.</div>`}function calendar(){return `${hdr('Market Calendar','Indian exchange sessions and corporate dates')}${demo()}<section class="card section"><div class="section-title">November 2026 · session calendar</div><div class="empty" style="margin-top:12px"><b>Exchange calendar is not connected</b>Trading sessions, holidays and special sessions must be verified against the current NSE/BSE calendar. Normal session signals are disabled in this demo.</div></section><section class="card section"><div class="section-title">Daily workflow</div>${['Pre-market: prior session, global context and events','During market: live scanning and validated triggers','Post-market: journal, costs and strategy review'].map(x=>`<div class="list-row"><span>${x}</span><b>Workflow template</b></div>`).join('')}</section>`}

